-- Тестовые данные для текущей schema.sql. Загружать после создания пустой схемы.
-- Ровно 500 записей: users 25, projects 10, project_members 50, sprints 25,
-- tasks 160, task_members 100, task_comments 100, task_parent 30.
-- Период событий: июль–ноябрь 2026 года; часовой пояс +03:00.
-- Пограничные случаи: NULL, нулевое время до обновления, сущности без операций.
-- Связи task_parent образуют деревья глубиной до двух рёбер, без циклов.

BEGIN;

-- Сотрудники разных ролей; пользователи 21–25 пока не участвуют в проектах и задачах (25 записей).

-- Все пять состояний проектов; проекты 6–10 без спринтов и задач (10 записей).

-- Участники нескольких проектов; в приостановленном проекте есть команда, но нет задач (50 записей).

-- По пять спринтов в пяти проектах; одинаковые названия спринтов в разных проектах (25 записей).

-- 150 задач в спринтах и 10 вне спринтов; все восемь статусов и три приоритета (160 записей).

-- Назначенные задачи, NULL исполнителя или автора, совпадение ролей; у 60 задач записи участников нет (100 записей).

-- По четыре комментария у 25 задач; повторные комментарии одного автора и NULL автора (100 записей).

-- Десять деревьев задач; общие родители и подзадачи второго уровня в пределах одного спринта (30 записей).

-- Явные ID требуют синхронизации последовательностей для последующих INSERT.
SELECT setval(pg_get_serial_sequence('users', 'id'), (SELECT MAX(id) FROM users), true);
SELECT setval(pg_get_serial_sequence('projects', 'id'), (SELECT MAX(id) FROM projects), true);
SELECT setval(pg_get_serial_sequence('sprints', 'id'), (SELECT MAX(id) FROM sprints), true);
SELECT setval(pg_get_serial_sequence('tasks', 'id'), (SELECT MAX(id) FROM tasks), true);
SELECT setval(pg_get_serial_sequence('task_comments', 'id'), (SELECT MAX(id) FROM task_comments), true);

COMMIT;
